/* Public listening controls over the source rows emitted by WebAddress. */
#ifndef BONFYRE_PUBLIC_AUDIO_DECK_H
#define BONFYRE_PUBLIC_AUDIO_DECK_H
#include "public_media_session.h"
static const char bf_public_audio_deck[] =
"<div class=\"deck bf-audio\" hidden data-deck tabindex=\"0\" role=\"region\" aria-label=\"Audio player\"><audio preload=\"none\"></audio><div class=\"bf-audio-head\"><div class=\"keys\"><button type=\"button\" data-deck-back aria-label=\"Previous recording\" disabled>Previous</button><button type=\"button\" data-deck-play aria-label=\"Play first recording\">Play</button><button type=\"button\" data-deck-next aria-label=\"Next recording\">Next</button></div><img class=\"art\" alt=\"\" hidden data-deck-art width=\"56\" height=\"56\" decoding=\"async\" referrerpolicy=\"no-referrer\"><div class=\"what\"><b data-deck-title>Choose a recording</b><span data-deck-by></span><span class=\"queue\" data-deck-queue></span></div></div><div class=\"bf-audio-progress\"><output data-deck-elapsed aria-label=\"Playback position\">0:00</output><input type=\"range\" data-deck-position min=\"0\" max=\"1000\" value=\"0\" step=\"1\" disabled aria-label=\"Seek in recording\"><output data-deck-duration aria-label=\"Recording duration\">Duration unavailable</output></div><div class=\"bf-audio-options\"><label>Volume<input type=\"range\" data-deck-volume min=\"0\" max=\"1\" step=\"0.05\" value=\"1\"></label><label>Speed<select data-deck-rate><option value=\"0.75\">0.75×</option><option value=\"1\" selected>1×</option><option value=\"1.25\">1.25×</option><option value=\"1.5\">1.5×</option><option value=\"2\">2×</option></select></label><button type=\"button\" data-deck-latest hidden disabled>Go to latest</button><a data-deck-page hidden>Open recording page</a><details data-deck-code hidden><summary>Open on another device</summary><div class=\"bf-audio-code\"><img data-deck-code-image width=\"240\" height=\"240\" alt=\"QR code for the selected public recording page\"><p>Opens this recording’s public page. Your account and listening position are not shared.</p><a data-deck-code-link download=\"aurekai-recording-code.svg\">Download QR code</a></div></details></div><details class=\"bf-audio-browser\" data-deck-browser><summary>Browse recordings</summary><label>Find in queue<input type=\"search\" data-deck-browser-search maxlength=\"160\" placeholder=\"Search these recordings\" aria-label=\"Find recording in this queue\"></label><ol data-deck-browser-list aria-label=\"Current source recordings\"></ol><p data-deck-browser-status role=\"status\" aria-live=\"polite\"></p></details><p data-deck-status role=\"status\" aria-live=\"polite\"></p></div>"
"<script>(function () {\n"
"'use strict';\n"
"const script=document.currentScript,deck=script.previousElementSibling;\n"
"let list=deck.previousElementSibling;while(list&&list.tagName==='STYLE')list=list.previousElementSibling;\n"
"if(!list||deck.dataset.ready)return;const rows=[...list.querySelectorAll('li[data-play]')];if(!rows.length)return;\n"
"deck.dataset.ready='true';deck.hidden=false;const find=name=>deck.querySelector('[data-deck-'+name+']');\n"
"const audio=deck.querySelector('audio'),play=find('play'),back=find('back'),next=find('next');\n"
"const position=find('position'),elapsed=find('elapsed'),duration=find('duration');\n"
"const volume=find('volume'),rate=find('rate'),title=find('title'),by=find('by');\n"
"const art=find('art'),queue=find('queue'),note=find('status'),page=find('page');\n"
"const code=find('code'),codeImage=find('code-image'),codeLink=find('code-link'),latest=find('latest');\n"
"let selected=-1,epoch=0,disposed=false,seeking=false,pending=false,resumePosition=0;const cleanups=[];\n"
"function on(target,event,handler){target.addEventListener(event,handler);cleanups.push(()=>target.removeEventListener(event,handler));}\n"
"function say(text){note.textContent=text;}\n"
"function time(seconds){if(!Number.isFinite(seconds)||seconds<0)return '0:00';const n=Math.floor(seconds),s=String(n%60).padStart(2,'0');return n>=3600?Math.floor(n/3600)+':'+String(Math.floor(n/60)%60).padStart(2,'0')+':'+s:Math.floor(n/60)+':'+s;}\n"
"function bounds(){\n"
" if(Number.isFinite(audio.duration)&&audio.duration>0)return [0,audio.duration];\n"
" const range=audio.seekable;if(audio.duration!==Infinity||!range?.length)return null;\n"
" try{const index=range.length-1,a=range.start(index),b=range.end(index);return Number.isFinite(a)&&Number.isFinite(b)&&a>=0&&b>a?[a,b]:null;}catch{return null;}}\n"
"function seek(value){const range=bounds();if(!range||!Number.isFinite(value))return false;try{audio.currentTime=Math.max(range[0],Math.min(range[1],value));}catch{return false;}resumePosition=0;controls();return true;}\n"
"function previewPosition(value,range){return audio.duration===Infinity?time(Math.max(0,range[1]-value))+' behind latest':time(value);}\n"
"function restorePosition(){if(resumePosition>0&&bounds()&&seek(resumePosition))resumePosition=0;}\n"
"function controls(){\n"
" const playing=!audio.paused&&!audio.ended;play.textContent=playing?'Pause':'Play';\n"
" play.setAttribute('aria-label',(playing?'Pause ':'Play ')+(selected<0?'first recording':title.textContent));\n"
" back.disabled=selected<0;next.disabled=selected>=rows.length-1;\n"
" for(let i=0;i<rows.length;i++){const button=rows[i].querySelector('.lift');if(button)button.setAttribute('aria-pressed',String(i===selected&&playing));}\n"
" const range=bounds(),finite=Number.isFinite(audio.duration)&&audio.duration>0;position.disabled=!range;\n"
" latest.hidden=audio.duration!==Infinity;latest.disabled=!range||range[1]-audio.currentTime<1;\n"
" if(!seeking)position.value=range?String(Math.min(1000,Math.max(0,(audio.currentTime-range[0])/(range[1]-range[0])*1000))):'0';\n"
" elapsed.textContent=range?previewPosition(audio.currentTime,range):time(audio.currentTime);\n"
" duration.textContent=finite?time(audio.duration):range?time(range[1]-range[0])+' window':audio.duration===Infinity?'Streaming':'Duration unavailable';\n"
" position.setAttribute('aria-label',audio.duration===Infinity?'Seek within available stream':'Seek in recording');\n"
" position.setAttribute('aria-valuetext',range?(finite?time(audio.currentTime)+' of '+time(audio.duration):previewPosition(audio.currentTime,range)+'; '+time(range[1]-range[0])+' available'):'Seeking unavailable');}\n"
"function stopPeers(event){if(event.detail!==deck){epoch++;pending=false;audio.pause();controls();}}\n"
"async function start(){\n"
" if(disposed||selected<0)return;const ticket=++epoch;pending=true;say('Loading recording…');\n"
" audio.defaultPlaybackRate=Number(rate.value);audio.playbackRate=Number(rate.value);audio.volume=Number(volume.value);\n"
" document.dispatchEvent(new CustomEvent('bonfyre:public-audio-play',{detail:deck}));\n"
" try{await audio.play();if(!disposed&&ticket===epoch){pending=false;say('Playing');controls();}}\n"
" catch(error){if(!disposed&&ticket===epoch){pending=false;say(error.name==='NotAllowedError'?'Press Play to allow audio in this browser.':'This recording could not play. Open its page or try Play again.');controls();}}}\n"
"function address(row){\n"
" const anchor=row.querySelector('a[href^=\"/o/\"]')||row.querySelector('a[href]');let url=null;\n"
" try{const proposed=new URL(anchor?.getAttribute('href')||'',location.href);if(anchor&&['http:','https:'].includes(proposed.protocol)&&!proposed.username&&!proposed.password)url=proposed;}catch{}\n"
" page.hidden=!url;if(url)page.href=url.href;else page.removeAttribute('href');\n"
" const native=url&&url.origin===location.origin&&/^\\/o\\/[a-z0-9._-]+\\/[a-f0-9]{24}$/.test(url.pathname)&&!url.search;\n"
" code.open=false;code.hidden=!native;codeImage.removeAttribute('src');codeImage.removeAttribute('data-src');\n"
" if(native){const href=url.pathname+'.qr.svg';codeImage.dataset.src=href;codeLink.href=href;}else codeLink.removeAttribute('href');}\n"
"function select(index,go=true){\n"
" if(disposed||index<0||index>=rows.length)return;const row=rows[index];let url;\n"
" try{url=new URL(row.dataset.play,location.href);if(!['http:','https:'].includes(url.protocol)||url.username||url.password)throw Error();}\n"
" catch{say('The recording address is unavailable. Open its page.');return;}\n"
" epoch++;pending=false;resumePosition=0;audio.pause();selected=index;\n"
" for(const entry of rows)entry.removeAttribute('aria-current');row.setAttribute('aria-current','true');\n"
" audio.src=url.href;audio.playbackRate=Number(rate.value);audio.volume=Number(volume.value);\n"
" title.textContent=row.dataset.title||'Selected recording';by.textContent=row.dataset.by||'';\n"
" const image=row.dataset.art;if(image){art.src=image;art.hidden=false;}else{art.removeAttribute('src');art.hidden=true;}\n"
" queue.textContent=(index+1)+' of '+rows.length;address(row);controls();updateBrowse();say(go?'Loading recording…':'Ready');if(go)void start();}\n"
"function toggle(){\n"
" if(selected<0){select(0);return;}\n"
" if(pending||!audio.paused){epoch++;pending=false;audio.pause();say('Paused');controls();}else void start();}\n"
"rows.forEach((row,index)=>{const button=row.querySelector('.lift');if(button)on(button,'click',()=>select(index));});\n"
"const browser=deck.querySelector('[data-deck-browser]');\n"
"const browseSearch=deck.querySelector('[data-deck-browser-search]');\n"
"const browseList=deck.querySelector('[data-deck-browser-list]');\n"
"const browseStatus=deck.querySelector('[data-deck-browser-status]');\n"
"const browseButtons=[];\n"
"rows.forEach((row,index)=>{\n"
" const entry=document.createElement('li'),item=document.createElement('button');\n"
" item.type='button';item.textContent=(index+1)+'. '+(row.dataset.title||'Untitled recording')+(row.dataset.by?' · '+row.dataset.by:'');\n"
" item.dataset.queueIndex=String(index);entry.append(item);browseList.append(entry);browseButtons.push(item);\n"
" on(item,'click',()=>{select(index);browser.open=false;});\n"
"});\n"
"function updateBrowse(){\n"
" const query=browseSearch.value.trim().toLocaleLowerCase();let matching=0;\n"
" browseButtons.forEach((button,index)=>{const yes=!query||button.textContent.toLocaleLowerCase().includes(query);\n"
"   button.parentElement.hidden=!yes;button.setAttribute('aria-current',String(index===selected));if(yes)matching++;});\n"
" browseStatus.textContent=matching+' of '+rows.length+' retained recordings in this page.';\n"
"}\n"
"on(browseSearch,'input',updateBrowse);\n"
"on(browser,'keydown',event=>{if(event.key==='Escape'){event.stopPropagation();event.preventDefault();browser.open=false;browser.querySelector('summary')?.focus();}});\n"
"updateBrowse();\n"
"on(play,'click',toggle);on(next,'click',()=>select(selected+1));\n"
"on(back,'click',()=>{const range=bounds();if(range&&audio.currentTime-range[0]>3)seek(range[0]);else select(Math.max(0,selected-1));});\n"
"on(position,'input',()=>{const range=bounds();seeking=!!range;if(range){const seconds=range[0]+Number(position.value)/1000*(range[1]-range[0]);elapsed.textContent=previewPosition(seconds,range);}});\n"
"on(position,'change',()=>{const range=bounds();seeking=false;if(range)seek(range[0]+Number(position.value)/1000*(range[1]-range[0]));controls();});\n"
"on(position,'blur',()=>{seeking=false;controls();});\n"
"on(latest,'click',()=>{const range=bounds();if(audio.duration===Infinity&&range&&seek(range[1]-Math.min(.1,(range[1]-range[0])/2)))say('Moved to the latest available audio');});\n"
"on(volume,'input',()=>{audio.volume=Math.min(1,Math.max(0,Number(volume.value)));});\n"
"on(rate,'change',()=>{audio.defaultPlaybackRate=Number(rate.value);audio.playbackRate=Number(rate.value);});\n"
"on(code,'toggle',()=>{if(code.open&&codeImage.dataset.src)codeImage.src=codeImage.dataset.src;});\n"
"on(audio,'loadedmetadata',()=>{audio.defaultPlaybackRate=Number(rate.value);audio.playbackRate=Number(rate.value);audio.volume=Number(volume.value);restorePosition();});\n"
"on(audio,'progress',restorePosition);\n"
"for(const event of ['loadedmetadata','durationchange','timeupdate','progress','emptied','seeked','play','pause'])on(audio,event,controls);\n"
"on(audio,'playing',()=>{pending=false;say('Playing');controls();});\n"
"on(audio,'waiting',()=>{if(!audio.paused)say('Buffering…');});\n"
"on(audio,'error',()=>{pending=false;say('This recording is unavailable here. Open its page or try Play again.');controls();});\n"
"on(audio,'ended',()=>{pending=false;if(selected+1<rows.length)select(selected+1);else{say('End of this selection');controls();}});\n"
"// Keyboard commands belong to this focused player, not to the document.\n"
"on(deck,'keydown',event=>{\n"
" if(event.target!==deck||event.repeat||event.ctrlKey||event.metaKey)return;\n"
" if(event.code==='Space'&&!event.altKey){event.preventDefault();toggle();}\n"
" else if(event.altKey&&event.key==='ArrowRight'){event.preventDefault();if(!next.disabled)next.click();}\n"
" else if(event.altKey&&event.key==='ArrowLeft'){event.preventDefault();if(!back.disabled)back.click();}});\n"
"function suspend(){epoch++;pending=false;if(audio.getAttribute('src')&&Number.isFinite(audio.currentTime))resumePosition=audio.currentTime;audio.pause();audio.removeAttribute('src');audio.load();say(selected<0?'Choose a recording to listen':'Playback stopped when you left this page');controls();}\n"
"function restore(){if(!disposed&&selected>=0&&!audio.getAttribute('src')){audio.src=rows[selected].dataset.play;audio.defaultPlaybackRate=Number(rate.value);audio.playbackRate=Number(rate.value);audio.volume=Number(volume.value);controls();}}\n"
"function dispose(){if(disposed)return;suspend();disposed=true;cleanups.splice(0).forEach(fn=>fn());}\n"
BF_PUBLIC_MEDIA_SESSION
"on(document,'bonfyre:public-audio-play',stopPeers);on(window,'pagehide',suspend);on(window,'pageshow',restore);\n"
"on(document,'htmx:beforeCleanupElement',event=>{const node=event.detail?.elt;if(node&&(node===deck||node.contains(deck)))dispose();});\n"
"controls();say('Choose a recording to listen');\n"
"})();</script>";
#endif
